#include <iostream>
using namespace std;
int main() {
    int a[4] = {3, 1, 2, 0};
    for (int j = 0; j < 3; j++) {
        if (a[j] > a[j + 1]) { int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t; }
    }
    for (int i = 0; i < 4; i++) cout << a[i] << " ";
    return 0;
}

#include <iostream>
using namespace std;
void sw(int a, int b) { int t = a; a = b; b = t; }
int main() {
    int x = 1, y = 2;
    sw(x, y);
    cout << x << y;
    return 0;
}

